<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-calendar-check" title="Laporan Kehadiran" subtitle="Rekap seluruh pegawai per bulan" /><div class="toolbar"><input v-model="filters.bulan" type="month" class="form-control form-control-sm"><button class="btn btn-primary btn-sm" @click="loadData"><i class="fas fa-search"></i></button><button class="btn btn-outline-success btn-sm" :disabled="exporting" @click="exportFile('excel')">XLSX</button><button class="btn btn-outline-danger btn-sm" :disabled="exporting" @click="exportFile('pdf')">PDF</button></div><div class="legend"><span>H Hadir</span><span>A Absen</span><span>I Izin</span><span>C Cuti</span><span>L Libur</span></div><div v-if="loading" class="empty">Memuat laporan...</div><div v-else-if="!rows.length" class="empty">Tidak ada data.</div><div v-else class="employees"><button v-for="r in rows" :key="r.pegawai_id||r.nip" class="employee" type="button" @click="openDetail(r)"><div class="employee-top"><div><strong>{{r.nama}}</strong><small>{{r.nip}} · {{r.jabatan||'-'}}</small></div><i class="fas fa-chevron-right"></i></div><div class="stats"><span class="h">H {{count(r,'H')}}</span><span class="a">A {{count(r,'A')}}</span><span class="i">I {{count(r,'I')}}</span><span class="c">C {{count(r,'C')}}</span><span class="l">L {{count(r,'L')}}</span></div><div class="strip"><span v-for="d in days" :key="d" :class="['dot',cellClass(r.harian?.[d])]" :title="cellTitle(r.harian?.[d],d)">{{r.harian?.[d]?.code||'-'}}</span></div></button></div><div v-if="detailOpen" class="modal-bg" @click.self="closeDetail"><section class="sheet"><div class="handle"></div><div class="sheet-head"><div><span>Detail Pegawai</span><h6>{{selectedEmployee?.nama||'-'}}</h6></div><button @click="closeDetail"><i class="fas fa-times"></i></button></div><div v-if="detailLoading" class="empty">Memuat detail...</div><div v-else class="detail"><div class="detail-box"><span>Periode</span><strong>{{monthLabel}}</strong></div><div v-for="x in 