<script setup>import PwaPageHeader from '../../../components/PwaPageHeader.vue';defineProps({filters:{type:Object,required:true},rows:{type:Array,default:()=>[]},days:{type:Array,default:()=>[]},loading:Boolean,exporting:Boolean,detailOpen:Boolean,detailLoading:Boolean,selectedEmployee:{type:Object,default:null},detailData:{type:Object,default:null},monthLabel:{type:String,default:''},cellClass:{type:Function,required:true},cellTitle:{type:Function,required:true},formatDate:{type:Function,required:true},formatTime:{type:Function,required:true},locationLabel:{type:Function,required:true},loadData:{type:Function,required:true},exportFile:{type:Function,required:true},openDetail:{type:Function,required:true},closeDetail:{type:Function,required:true}});const count=(r,c)=>Object.values(r.harian||{}).filter(x=>x?.code===c).length</script>
<style scoped>.attendance-pwa{padding:2px 0 84px}.toolbar{display:grid;grid-template-columns:1fr auto auto auto;gap:4px;padding:8px;margin-bottom:5px;background:#fff;border:1px solid #e5e7eb;border-radius:14px}.toolbar .form-control{font-size:11.25px}.toolbar .btn{font-size:9.38px;font-weight:900}.legend{display:flex;gap:7px;overflow-x:auto;padding:2px 0 7px;color:#64748b;font-size:9.38px;font-weight:800}.employees{display:flex;flex-direction:column;gap:6px}.employee{width:100%;text-align:left;padding:8px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.employee-top{display:flex;justify-content:space-between;gap:6px}.employee-top strong{display:block;font-size:12.25px;color:#111827}.employee-top small{display:block;color:#64748b;font-size:9.12px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:270px}.employee-top i{color:#94a3b8;font-size:10px}.stats{display:flex;gap:4px;margin-top:6px}.stats span{padding:3px 4px;border-radius:5px;font-size:8.5px;font-weight:900}.stats .h{background:#dcfce7;color:#166534}.stats .a{background:#fee2e2;color:#991b1b}.stats .i{background:#cffafe;color:#0e7490}.stats .c{background:#fef3c7;color:#92400e}.stats .l{background:#ede9fe;color:#6d28d9}.strip{display:grid;grid-template-columns:repeat(31,1fr);gap:2px;margin-top:6px}.dot{height:13px;border-radius:3px;background:#f8fafc;color:#94a3b8;display:flex;align-items:center;justify-content:center;font-size:6.88px;font-weight:900}.dot.hadir{background:#dcfce7;color:#166534}.dot.absen{background:#fee2e2;color:#991b1b}.dot.izin{background:#cffafe;color:#0e7490}.dot.cuti{background:#fef3c7;color:#92400e}.dot.libur{background:#ede9fe;color:#6d28d9}.empty{min-height:120px;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#64748b;font-size:11.25px}.modal-bg{position:fixed;inset:0;z-index:2400;background:rgba(15,23,42,.35);display:flex;align-items:flex-end}.sheet{width:100%;max-height:78dvh;overflow:auto;background:#fff;